import{_ as a,c as i,o as r,a2 as o}from"./chunks/framework.bjzS3PU6.js";const p=JSON.parse('{"title":"GUMM1","description":"","frontmatter":{},"headers":[],"relativePath":"entries/people/GUMM1.md","filePath":"entries/people/GUMM1.md"}'),n={name:"entries/people/GUMM1.md"};function t(s,e,l,c,h,m){return r(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="gumm1" tabindex="-1">GUMM1 <a class="header-anchor" href="#gumm1" aria-label="Permalink to &quot;GUMM1&quot;">​</a></h1><hr><p><strong>OCCUPATION</strong>: Computer security researcher, activist<br><strong>ORGANIZATION</strong>: The Bloc (co-founder, 1999)<br><strong>ACTIVE</strong>: 1999–present<br><strong>STATUS</strong>: Active</p><hr><p><strong>GUMM1</strong> (also known as <strong>Gummi</strong> or <strong>Gummy</strong>) is an American computer security researcher and activist. They are best known as a co-founder of <a href="./../organizations/The-Bloc">The Bloc</a>, an organization that investigates alleged corporate misconduct by the <a href="./../organizations/Miter-Corporation">Miter Corporation</a> and related entities.</p><p><strong>At a glance</strong></p><ul><li>Co-founded The Bloc (1999) with <a href="./Z-L1NE">Z*L1NE</a> and <a href="./1NK">1NK</a></li><li>Co-authored <em>G</em>BOY Manifesto: Sigils, Symbols, and Memetic Rebellion* (1999)</li><li>Specializes in data analysis and computer security research</li><li>Active in ongoing investigations into <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a></li><li>Family member targeted by alleged Harmony Program operations</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>GUMM1 is one of three founding members of The Bloc, alongside <a href="./Z-L1NE">Z*L1NE</a> and <a href="./1NK">1NK</a>. The organization was formed in 1999 following the discovery of classified research materials obtained from <a href="./../organizations/Miter-Corporation">Miter Corporation</a> secure servers. GUMM1 functions as one of the group&#39;s primary technical researchers specializing in data extraction and analysis.</p><p>The Bloc operates as an underground watchdog organization investigating what it claims are illegal research operations involving human subjects. The group gained prominence following the escape of <a href="./../subjects/G-BOY">G*BOY (Subject G-304)</a> from Saint Juniper Research Campus.</p><h2 id="career-and-activism" tabindex="-1">Career and activism <a class="header-anchor" href="#career-and-activism" aria-label="Permalink to &quot;Career and activism&quot;">​</a></h2><h3 id="formation-of-the-bloc" tabindex="-1">Formation of The Bloc <a class="header-anchor" href="#formation-of-the-bloc" aria-label="Permalink to &quot;Formation of The Bloc&quot;">​</a></h3><p>GUMM1 met <a href="./Z-L1NE">Z*L1NE</a> at the <a href="./../locations/St-Juniper-Paranormal-Museum">St. Juniper Paranormal Museum</a> around 1999. Along with fellow researcher <a href="./1NK">1NK</a>, who had gained unauthorized access to Miter Corporation systems, the three formed The Bloc and established operations in basement facilities provided by the <a href="./../locations/St-Juniper-Paranormal-Museum">museum</a>&#39;s proprietor, <a href="./Magdalena">Magdalena</a>.</p><p>The founding members published <em>G</em>BOY Manifesto: Sigils, Symbols, and Memetic Rebellion* in 1999, which outlined their analysis of alleged corporate control mechanisms and positioned The Bloc as an activist organization resisting what they termed &quot;coercive homogeny.&quot;</p><h3 id="ongoing-operations" tabindex="-1">Ongoing operations <a class="header-anchor" href="#ongoing-operations" aria-label="Permalink to &quot;Ongoing operations&quot;">​</a></h3><p>GUMM1 continues to participate in The Bloc&#39;s research activities. Recent communications indicate ongoing data gathering efforts related to the research campus and its secure networks. GUMM1&#39;s technical work focuses on extracting and analyzing materials from compromised systems, working in coordination with <a href="./1NK">1NK</a> and <a href="./Z-L1NE">Z*L1NE</a>.</p><h2 id="technical-expertise" tabindex="-1">Technical expertise <a class="header-anchor" href="#technical-expertise" aria-label="Permalink to &quot;Technical expertise&quot;">​</a></h2><p>GUMM1 specializes in computer security research and data analysis. Within The Bloc&#39;s structure, they function as a technical researcher responsible for processing and interpreting materials obtained from secure institutional systems.</p><h2 id="personal-life" tabindex="-1">Personal life <a class="header-anchor" href="#personal-life" aria-label="Permalink to &quot;Personal life&quot;">​</a></h2><p>GUMM1 resides in the Saint Juniper area and maintains family connections in the region. According to The Bloc&#39;s allegations, a family member (an elderly relative) was targeted by what the organization claims are operations involving <a href="./../concepts/Harmony">Harmony</a>—a pharmaceutical initiative that The Bloc alleges has undisclosed cognitive effects on participants.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./Z-L1NE">Z*L1NE</a></li><li><a href="./1NK">1NK</a></li><li><a href="./Magdalena">Magdalena</a></li><li><a href="./Kai-Shepherd">Kai Shepherd</a></li><li><a href="./../locations/Hill-Devil-State-Park">Hill Devil State Park</a></li><li><a href="./../locations/St-Juniper-Paranormal-Museum">St. Juniper Paranormal Museum</a></li><li><a href="./../organizations/The-Bloc">The Bloc</a></li><li><a href="./../organizations/Miter-Corporation">Miter Corporation</a></li><li><a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a></li><li><a href="./../subjects/G-BOY">G*BOY (Subject G-304)</a></li><li><a href="./../concepts/Harmony">Harmony</a></li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li><em>G</em>BOY Manifesto: Sigils, Symbols, and Memetic Rebellion* (1999) — Founding document co-authored by 1NK, Z-L1N3, and GUMM1</li><li>&quot;The Bloc: Saint Juniper&#39;s Paranormal Activists,&quot; coverage of activist organization</li><li>Online communications from The Bloc network (2025)</li></ol><hr><p><em>This article is part of the Saint Juniper Research Documentation Project</em></p>',26)])])}const u=a(n,[["render",t]]);export{p as __pageData,u as default};
